  red: color2("\x1B[31m"),
  yellow: color2("\x1B[33m"),
  blue: color2("\x1B[34m"),
  cyan: color2("\x1B[36m"),
  magenta: color2("\x1B[35m"),
  redBadge: color2("\x1B[41m\x1B[30m\x1B[1m"),
  yellowBadge: color2("\x1B[43m\x1B[30m\x1B[1m"),
  cyanBadge: color2("\x1B[46m\x1B[30m\x1B[1m")
